/*

This is a javascript file that is used for a specific Pattern

The following callback funtions are registered by a toolkit plugin :

/com.ibm.etools.mft.patterns/src/com/ibm/etools/mft/patterns/views/PatternManager.java
/com.ibm.etools.mft.patterns/src/com/ibm/etools/mft/patterns/views/PatternStepsView.java

Callback functions:
javaOpenURLInExternalBrowserFunction
javaImportPIFileFunction
javaGetSelectedPatternFunction
javaUnDeployResourcesFunction
javaDeleteProjectsFromWorkspaceFunction
javaOpenResourceEditorPatternFunction

*/

import { Time16, Download16, TrashCan16 } from '@carbon/icons-react'
import {
  Button,
  Link,
  Accordion,
  AccordionItem,
  OrderedList,
  UnorderedList,
  ListItem
} from 'carbon-components-react'
import parse from 'html-react-parser'
import React, { useEffect, useState } from 'react'

import repoMetadata from '../repo_metadata.json'

import './PatternPage.scss'

const repoMetadataUrl = 'https://ot4i.github.io/ace-tutorials/v13/en/patterns_repo_metadata.json'
const repoUrl = 'https://ot4i.github.io/'
const fileUrl = '/v12/en/data.json'

const TopicsListItems = ({ topics }) => {
  const result = []
  for (const topic of topics) {
    result.push(
      <ListItem className='pattern-preview__' key={topic.title}>
        {topic.title}
      </ListItem>
    )
  }

  return result
}

const OutcomesListItems = ({ outcomes }) => {
  const result = []

  for (const outcome of outcomes) {
    result.push(
      <ListItem className='pattern-preview__outcome' key={outcome.title}>
        {outcome.title}
      </ListItem>
    )
  }

  return result
}

export const PatternPage = route => {
  const [patternData, setPatternData] = useState(null)

  const patternName = route.match.params.pattern

  useEffect(() => {
    const fetchJsonFile = async () => {
      const response = await fetch(repoUrl + patternName + fileUrl, {
        headers: new Headers({
          Accept: 'application/vnd.github.v3+json'
        }),
        method: 'GET',
        mode: 'cors',
        credentials: 'omit' // Useful for including session ID (and, IIRC, authorization headers)
      })
      const responseData = await response.json()

      if (responseData) {
        setPatternData(responseData)
      }
    }

    fetchJsonFile()
  }, [patternName])

  // Fetches latest repo_metadata from public Github
  const [patternsData, setPatternsData] = useState(null)
  useEffect(() => {
    const fetchPatternsData = async () => {
      const response = await fetch(repoMetadataUrl, {
        headers: new Headers({
          Accept: 'application/vnd.github.v3+json'
        }),
        method: 'GET',
        mode: 'cors',
        credentials: 'omit' // Useful for including session ID (and, IIRC, authorization headers)
      })

      const responseData = await response.json()
      if (responseData) {
        setPatternsData(responseData)
      }
    }

    // Uncomment next line if you want to use the local copy of repo_metadata.json
    fetchPatternsData()
  }, [])

  const pageSteps = patternData?.pattern?.pageSteps
  const pageTitle = patternData?.pattern?._common?.name
  const pageSubTitle = patternData?.pattern?._common?.shortDescription
  const createStep = pageSteps?.create
  const prepareStep = pageSteps?.prepare
  const runStep = pageSteps?.run

  const helpLinkUrl = patternData?.pattern?._common?.helpLink?.link
  const helpLinkText = patternData?.pattern?._common?.helpLink?.text
  const onHelpLinkClick = e => {
    e.preventDefault()

    try {
      window.javaOpenURLInExternalBrowserFunction(helpLinkUrl)
    } catch (e) {
      alert('a java error in javaOpenURLInExternalBrowserFunction occurred: ' + e.message)
    }
  }

  const onLinkClick = (evt, url) => {
    evt.preventDefault()

    try {
      window.javaOpenURLInExternalBrowserFunction(url)
    } catch (e) {
      alert('a java error in javaOpenURLInExternalBrowserFunction occurred: ' + e.message)
    }
  }

  const onImportArtifactClick = (evt, patternsData) => {
    evt.preventDefault()

    const patternName = pageTitle
    const fetchedPatternsData = patternsData && patternsData.categories && patternsData.categories[0] && patternsData.categories[0].patterns
    const foundPatternsData = fetchedPatternsData && fetchedPatternsData.find(({ name }) => name === patternName)
    const repoMetadataPattern = foundPatternsData || repoMetadata.categories[0].patterns.find(({ name }) => name === patternName)
    const zipUrl = repoMetadataPattern && repoMetadataPattern.zipURL

    try {
      window.javaImportPIFileFunction(patternName, zipUrl)
    } catch (e) {
      alert('a java error in javaOpenURLInExternalBrowserFunction occurred: ' + e.message)
    }

    if (repoMetadataPattern && repoMetadataPattern.editorResPaths && repoMetadataPattern.editorResPaths.length) {
      const resourceId = repoMetadataPattern.editorResPaths[0].id
      resourceId && onOpenResource(resourceId)
    }
  }

  const onBacktoGalleryClick = evt => {
    evt.preventDefault()

    try {
      window.javaBackToGalleryFunction()
    } catch (e) {
      alert('a java error in javaBackToGalleryFunction occurred: ' + e.message)
    }
  }

  const onCleanUpClick = evt => {
    evt.preventDefault()

    let result = null
    let tut = null

    /* eslint-disable no-undef */
    try {
      result = javaGetSelectedPatternFunction()
      const tutInfoString = result[0]
      tut = JSON.parse(tutInfoString)
    } catch (e) {
      alert('a java error in javaGetSelectedPatternFunction occurred: ' + e.message)
    }

    if (tut !== undefined) {
      try {
        result = javaUnDeployResourcesFunction()
      } catch (e) {
        alert('a java error in javaUnDeployResourcesFunction occurred: ' + e.message)
      }

      try {
        result = javaDeleteProjectsFromWorkspaceFunction(tut.projects.split(':'))
      } catch (e) {
        alert('a java error in javaDeleteProjectsFromWorkspaceFunction occurred: ' + e.message)
      }
    }
    /* eslint-enable no-undef */
  }

  const onOpenResource = id => {
    try {
      window.javaOpenResourceEditorPatternFunction(id)
    } catch (e) {
      alert('a java error in javaOpenResourceEditorPatternFunction occurred: ' + e.message)
    }
  }

  const details = patternData?.pattern?.pageDetails || ''
  const common = patternData?.pattern?._common || ''
  const summary = patternData?.pattern?.pageDetails?.summary || {}

  if (patternData) {
    // Possible refresh fix for a single pattern, might fix blank pages issue
    if (patternsData && patternsData.categories && patternsData.categories[0] && patternsData.categories[0].patterns) {
      if (window.localStorage) {
        if (!localStorage.getItem('firstLoad')) { // AppScan obfuscation
          localStorage.firstLoad = true
          window.location.reload()
        } else {
          localStorage.removeItem('firstLoad')
        }
      }
    }

    return (
      <div className='pattern-page__pattern'>
        <div className='patterns-page__pattern--title-container'>
          <h3 className='patterns-page__pattern--title'>
            {pageTitle}
          </h3>
          <Link
            href='#'
            onClick={e => onBacktoGalleryClick(e)}
            className='patterns-page__pattern--title-link'
          >
            Back to gallery
          </Link>
        </div>
        <hr className='patterns-page__pattern--hr' />
        <div className='patterns-page__pattern--content-container'>
          <div className='patterns-page__pattern--subtitle-container'>
            <p className='patterns-page__pattern--subtitle'>
              {pageSubTitle}
            </p>
            <Link
              href='#'
              onClick={e => onHelpLinkClick(e)}
              className='patterns-page__pattern--subtitle-link'
            >
              {helpLinkText}
            </Link>
          </div>
          <br />
          <Accordion size='xl'>

            {/*
              Overview Step
            */}
            <AccordionItem
              title='Overview'
              className='pattern-stage pattern-stage--overview'
              key='pattern-stage-overview'
            >
              <div className='pattern-preview'>
                <div className='pattern-preview__section'>
                  <span />
                  <h6>{common.shortDescription}</h6>
                </div>
                <div className='pattern-preview__section pattern-preview__section--row pattern-preview__schedule--container'>
                  <div className='pattern-preview__schedule' title='Estimated pattern duration time'>
                    <Time16 className='pattern-preview__icon' />
                    <p>{common.durationTime}.</p>
                  </div>
                </div>
                <div className='pattern-preview__section'>
                  <p className='pattern-preview__text'>{details.topicsName}</p>
                  <UnorderedList className='pattern-preview__list'>
                    <TopicsListItems topics={details.topicList} />
                  </UnorderedList>
                </div>
                <div className='pattern-preview__section'>
                  <p className='pattern-preview__text'>{details.outcomesName}</p>
                  <UnorderedList className='pattern-preview__list'>
                    <OutcomesListItems outcomes={details.outcomeList} />
                  </UnorderedList>
                </div>
                <div className='pattern-preview__section'>
                  <p className='pattern-preview__text-header'>
                    {
                      (summary && summary.overviewName) === 'OVERVIEW'
                        ? 'Details'
                        : summary.overviewName
                    }
                  </p>
                  {summary && summary.sections && summary.sections.map((item, index) => (
                    <p key={`item-section:${index}`} className='pattern-preview__text'>
                      {item.section}
                    </p>
                  ))}
                </div>
              </div>
            </AccordionItem>

            {/*
              Create Step
            */}
            <AccordionItem
              title='Create'
              className='pattern-stage pattern-stage--create'
              key='pattern-stage-create'
              open
            >
              <div className='pattern-preview'>
                <div className='pattern-preview__section pattern-preview__section-inline'>
                  <h6 className='pattern-preview__section-header'>{createStep.overview.heading}</h6>
                  {
                  createStep && createStep.actions && createStep.actions.details && createStep.actions.details.map((detail, detailIndex) =>
                    detail.method === 'importArtifacts()' && (
                      <Button
                        href='#'
                        onClick={e => onImportArtifactClick(e, patternsData)}
                        size='sm'
                        key={`createStep-button:${detailIndex}`}
                        renderIcon={Download16}
                        className='pattern-preview__section-button'
                      >
                        {detail.name}
                      </Button>
                    )
                  )
                }
                </div>
                <div className='pattern-preview__section'>
                  {createStep && createStep.overview && createStep.overview.sections && createStep.overview.sections.map((section, sectionIndex) => (
                    <div key={`item-container:${sectionIndex}`}>
                      <p key={`item-section:${sectionIndex}`} className='pattern-preview__text'>
                        {section && section.section && parse(section.section)}
                      </p>
                      {
                      section.steps && section.steps.details && section.steps.details.map((detail, detailIndex) => (
                        <p key={`item-section:${detailIndex}`} className='pattern-preview__text'>
                          {detail && detail.details && parse(detail.details)}
                        </p>
                      ))
                    }
                    </div>
                  ))}
                </div>
                <br />
                <div className='pattern-preview__section'>
                  <h6 className='pattern-preview__section-header'>{createStep?.helpLinks?.title}</h6>
                  {createStep && createStep.helpLinks && createStep.helpLinks.details && createStep.helpLinks.details.map((detail, detailIndex) => (
                    <div key={`item-container-create-help:${detailIndex}`}>
                      <Link
                        key={`item-section-create-help:${detailIndex}`}
                        href='#'
                        onClick={e => onLinkClick(e, detail.link)}
                      >
                        {detail.description}
                      </Link>
                    </div>
                  ))}
                </div>
              </div>
            </AccordionItem>

            {/*
              Prepare Step
              onHeadingClick={(obj) => onAccordionClick(obj, 2)}
            */}
            <AccordionItem
              title='Prepare'
              className='pattern-stage pattern-stage--prepare'
              key='pattern-stage-prepare'
            >
              <div className='pattern-preview'>
                <div className='pattern-preview__section pattern-preview__section-inline'>
                  <h6 className='pattern-preview__section-header'>{prepareStep.overview.heading}</h6>
                </div>
                <div className='pattern-preview__section'>
                  {prepareStep && prepareStep.overview && prepareStep.overview.sections && prepareStep.overview.sections.map((section, sectionIndex) => (
                    <div key={`item-container-prepare:${sectionIndex}`}>
                      <p key={`item-section-prepare:${sectionIndex}`} className='pattern-preview__text'>
                        {section && section.section && parse(section.section)}
                      </p>
                      <OrderedList className='pattern-preview__section--ordered-list'>
                        {
                        section.steps && section.steps.details && section.steps.details.map((detail, detailIndex) => (
                          <ListItem
                            key={`item-section-prepare:${detailIndex}`}
                            className='pattern-preview__section--list'
                          >
                            {detail && detail.details && parse(detail.details)}
                            {
                              detail && detail.substeps && detail.substeps.details.map((substep, substepIndex) => (
                                <ListItem
                                  key={`item-section-prepare:${substepIndex}`}
                                  className='pattern-preview__section--list pattern-preview__section--list-substep'
                                >
                                  {substep.details && parse(substep.details)}
                                </ListItem>
                              ))
                            }
                          </ListItem>
                        ))
                      }
                      </OrderedList>
                    </div>
                  ))}
                </div>
                <br />
                <div className='pattern-preview__section'>
                  <h6 className='pattern-preview__section-header'>{prepareStep?.helpLinks?.title}</h6>
                  {prepareStep && prepareStep.helpLinks && prepareStep.helpLinks.details && prepareStep.helpLinks.details.map((detail, detailIndex) => (
                    <div key={`item-container-prepare-help:${detailIndex}`}>
                      <Link
                        key={`item-section-prepare-help:${detailIndex}`}
                        href='#'
                        onClick={e => onLinkClick(e, detail.link)}
                      >
                        {detail.description}
                      </Link>
                    </div>
                  ))}
                </div>
              </div>
            </AccordionItem>

            {/*
              Run Step
            */}
            <AccordionItem
              title='Run'
              className='pattern-stage pattern-stage--run'
              key='pattern-stage-run'
            >
              <div className='pattern-preview'>
                <div className='pattern-preview__section pattern-preview__section-inline'>
                  <h6 className='pattern-preview__section-header'>{runStep.overview.heading}</h6>
                </div>
                <div className='pattern-preview__section'>
                  {runStep && runStep.overview && runStep.overview.sections && runStep.overview.sections.map((section, sectionIndex) => (
                    <div key={`item-container-run:${sectionIndex}`}>
                      <p key={`item-section-run:${sectionIndex}`} className='pattern-preview__text'>
                        {section && section.section && parse(section.section)}
                      </p>
                      <OrderedList className='pattern-preview__section--ordered-list'>
                        {
                          section.steps && section.steps.details && section.steps.details.map((detail, detailIndex) => (
                            <ListItem
                              key={`item-section-run-detail:${detailIndex}`}
                              className='pattern-preview__section--list'
                            >
                              {detail && detail.details && parse(detail.details)}
                              {
                                detail && detail.substeps && detail.substeps.details.map((substep, substepIndex) => (
                                  <ListItem
                                    key={`item-section-run:${substepIndex}`}
                                    className='pattern-preview__section--list pattern-preview__section--list-substep'
                                  >
                                    {substep.details && parse(substep.details)}
                                  </ListItem>
                                ))
                              }
                            </ListItem>
                          ))
                        }
                      </OrderedList>
                    </div>
                  ))}
                </div>
                <br />
                <div className='pattern-preview__section'>
                  <h6 className='pattern-preview__section-header'>{runStep?.helpLinks?.title}</h6>
                  {runStep && runStep.helpLinks && runStep.helpLinks.details && runStep.helpLinks.details.map((detail, detailIndex) => (
                    <div key={`item-container-run-help:${detailIndex}`}>
                      <Link
                        key={`item-section-run-help:${detailIndex}`}
                        href='#'
                        onClick={e => onLinkClick(e, detail.link)}
                      >
                        {detail.description}
                      </Link>
                    </div>
                  ))}
                </div>
                {
                  runStep && runStep.exits && runStep.exits.details && runStep.exits.details.length && (
                    <div className='pattern-preview__section'>
                      {
                        runStep && runStep.exits && runStep.exits.details && runStep.exits.details.map((detail, detailIndex) => (
                          <div key={`item-container-run-exit:${detailIndex}`}>
                            <h6 className='pattern-preview__section-header'>
                              {detail.cleanupDescription || detail.description}
                            </h6>
                            {
                              detail.method === 'cleanUp()' && (
                                <Button
                                  kind='danger--tertiary'
                                  key={`item-section-run-exit:${detailIndex}`}
                                  onClick={e => onCleanUpClick(e)}
                                  renderIcon={TrashCan16}
                                  iconDescription={detail.cleanupDescription || detail.description}
                                  size='sm'
                                  className='pattern-preview__section-button'
                                >
                                  {detail.name}
                                </Button>
                              )
                            }
                          </div>
                        ))
                      }
                    </div>
                  )
                }
              </div>
            </AccordionItem>
          </Accordion>
        </div>
      </div>
    )
  } else {
    return ''
  }
}
