import { IdeNavigation, IdeSideNavLink } from '@carbon/ibm-cloud-cognitive-cdai'
import {
  Home20,
  Education20,
  AddComment20,
  Language20
} from '@carbon/icons-react'
import {
  Header,
  HeaderName,
  HeaderMenuItem,
  HeaderNavigation
} from 'carbon-components-react'
import PropTypes from 'prop-types'
import React from 'react'
import { NavLink } from 'react-router-dom'
import './LayoutNav.scss'
import './LayoutGrid.scss'

const ariaAttributes = {
  'aria-labelledby': '#myId',
  'aria-label': 'sample aria label to describe the nav'
}

export const LayoutNav = ({ children }) => (
  <>
    <Header aria-label='IBM Toolkit'>
      <HeaderName href='#'>
        App Connect&nbsp;<span className='header-highlight'>Enterprise Toolkit</span>
      </HeaderName>
      <HeaderNavigation aria-label='IBM Toolkit'>
        <HeaderMenuItem href='https://org.eclipse.ui.intro/close'>
          Close page
        </HeaderMenuItem>
      </HeaderNavigation>
    </Header>
    <IdeNavigation
      ariaAttributes={ariaAttributes}
      navigationLinks={[
        <IdeSideNavLink
          key='link-welcome-top-level'
          renderIcon={Home20}
          element={NavLink}
          href='/welcome'
          to={{ pathname: '/welcome' }}
        >
          Welcome
        </IdeSideNavLink>,
        <IdeSideNavLink
          key='link-tutorials-top-level'
          renderIcon={Education20}
          element={NavLink}
          href='/tutorials'
          to={{ pathname: '/tutorials' }}
        >
          Tutorials
        </IdeSideNavLink>,
        <IdeSideNavLink
          key='link-patterns-top-level'
          renderIcon={Education20}
          element={NavLink}
          href='/patterns'
          to={{ pathname: '/patterns' }}
        >
          Patterns
        </IdeSideNavLink>,
        <IdeSideNavLink
          key='link-whatsnew-top-level'
          renderIcon={AddComment20}
          href='https://org.eclipse.ui.intro/showHelpTopic?id=/com.ibm.etools.mft.doc/bb23850_.html'
          to={{ pathname: 'https://org.eclipse.ui.intro/showHelpTopic?id=/com.ibm.etools.mft.doc/bb23850_.html' }}
        >
          <span>What&apos;s new</span>
        </IdeSideNavLink>,
        <IdeSideNavLink
          key='link-language-top-level'
          renderIcon={Language20}
          href='https://org.eclipse.ui.intro/showHelpTopic?id=/com.ibm.iib.langpacks.doc/bh25997_.htm'
          to={{ pathname: 'https://org.eclipse.ui.intro/showHelpTopic?id=/com.ibm.iib.langpacks.doc/bh25997_.htm' }}
        >
          <span>Language pack</span>
        </IdeSideNavLink>
      ]}
    >
      <div className='main-content carbon-theme--g10'>
        {children}
      </div>
    </IdeNavigation>
  </>
)

LayoutNav.propTypes = {
  children: PropTypes.node
}
