import { ArrowRight16, Time16 } from '@carbon/icons-react'
import { Button, ClickableTile, Tag } from 'carbon-components-react'
import PropTypes from 'prop-types'
import React, { useState } from 'react'

import './ListPanelItem.scss'

const startTutorial = (
  e,
  tutorialName,
  tutorialData
) => {
  e.preventDefault()
  e.stopPropagation()

  if (tutorialName && tutorialData) {
    const currentWindowHref = window.location.href
    // We'll use the current location to ease testing.
    // Main URL was 'https://ot4i.github.io/ace-tutorials/v12/en/#/./tutorials/'
    const tutorialsPageUrl = currentWindowHref + '/'

    const selectedTutorialUrl = tutorialData.stepsURL
    const selectedTutorialUrlSplit = selectedTutorialUrl.split('/')
    const tutorialRepoName = selectedTutorialUrlSplit[9]

    try {
      window.javaSetSelectedTutorialFunction(tutorialName)
    } catch (e) {
      alert('a java error in javaSetSelectedTutorialFunction occurred: ' + e.message)
    }

    try {
      window.javaOpenTutorialStepsFunction(tutorialsPageUrl + tutorialRepoName)
    } catch (e) {
      alert('a java error in javaOpenTutorialStepsFunction occurred: ' + e.message)
    }
  }
}

export const ListPanelItem = ({
  name,
  desc,
  categories,
  tags,
  durationMins,
  handleLinkClick,
  hasStartButton,
  hasDetailsButton,
  tutorialData
}) => {
  const baseClass = 'list-panel-item'
  const [active, setActive] = useState({
    focus: false,
    pointer: false
  })

  const [itemClasses, setItemClasses] = useState(baseClass)
  const handleClick = preview => {
    // console.log(`handleClick (pattern tile): ${preview}`)
    handleLinkClick(preview === true)
  }

  const updateItemClasses = newActive => {
    setItemClasses(
      newActive.focus || newActive.pointer
        ? `${baseClass} ${baseClass}--active`
        : `${baseClass}`
    )
  }

  const handleActivate = e => {
    const newState = { ...active }
    const type = e.type === 'focus' ? e.type : e.type.substr(0, e.type.length - 5)
    newState[type] = true
    setActive(newState)
    updateItemClasses(newState)
  }

  const handleDeactivate = e => {
    const newState = { ...active }
    const type = e.type === 'blur' ? 'focus' : e.type.substr(0, e.type.length - 5)
    newState[type] = false
    setActive(newState)
    updateItemClasses(newState)
  }

  return (
    <li
      className={itemClasses}
      onFocus={handleActivate}
      onBlur={handleDeactivate}
      onPointerEnter={handleActivate}
      onPointerLeave={handleDeactivate}
    >
      <ClickableTile light handleClick={handleClick} tabIndex='0'>
        <div className='list-panel-item__heading'>
          <h2 className='list-panel-item__title'>{name}</h2>
        </div>
        <p className='list-panel-item__text text--long'>
          {desc}
        </p>
        <div className='list-panel-item__lower'>
          <div className='list-panel-item__lower-left'>
            {
              durationMins && (
                <>
                  <Time16
                    className='list-panel-item__duration-img'
                    aria-label='Timing indicator'
                  />
                  <span className='list-panel-item__duration-text'>
                    {durationMins} minutes
                  </span>
                </>
              )
            }
            {
              tags && tags.map(tag =>
                <Tag key={tag}>{tag}</Tag>
              )
            }
          </div>
          <div className='list-panel-item__categories-right'>
            {
              categories && categories.map(cat =>
                <Tag key={cat}>{cat}</Tag>
              )
            }
          </div>
          {
            hasStartButton && (
              <Button
                kind='ghost'
                iconDescription='Start tutorial'
                renderIcon={ArrowRight16}
                size='sm'
                onClick={e => startTutorial(e, name, tutorialData)}
                className='list-panel-item__start-button'
              >
                Start
              </Button>
            )
          }
          {
            hasDetailsButton && (
              <Button
                kind='ghost'
                iconDescription='Pattern Details'
                renderIcon={ArrowRight16}
                size='sm'
                onClick={e => startTutorial(e, name, tutorialData)}
                className='list-panel-item__details-button'
              >
                Details
              </Button>
            )
          }
        </div>
      </ClickableTile>
    </li>
  )
}

ListPanelItem.propTypes = {
  name: PropTypes.node,
  desc: PropTypes.node,
  categories: PropTypes.arrayOf(PropTypes.string),
  tags: PropTypes.arrayOf(PropTypes.string),
  durationMins: PropTypes.node,
  handleLinkClick: PropTypes.func,
  hasStartButton: PropTypes.any,
  hasDetailsButton: PropTypes.any,
  tutorialData: PropTypes.any
}
