import './App.scss'

import React from 'react'
import { HashRouter, Switch, Route, Redirect } from 'react-router-dom'

import { PatternPage } from './Page/PatternPage.jsx'
import { PatternsPage } from './Page/PatternsPage.jsx'
import { TutorialPage } from './Page/TutorialPage.jsx'
import { TutorialsPage } from './Page/TutorialsPage.jsx'
import { WelcomePage } from './Page/WelcomePage.jsx'

function App () {
  return (
    <div className='App toolkit-prototype'>
      <HashRouter basename={process.env.PUBLIC_URL}>
        <Switch>
          <Route key='route-patterns-page' exact path='/patterns' component={PatternsPage} />
          <Route key='route-pattern-page' path='/patterns/:category/:pattern' component={PatternPage} />
          <Route key='route-tutorials-page' exact path='/tutorials' component={TutorialsPage} />
          <Route key='route-tutorial-page' path='/tutorials/:tutorial' component={TutorialPage} />
          <Route key='route-welcome-page' exact path='/welcome' component={WelcomePage} />
          <Redirect exact from='/' to='/welcome' />
        </Switch>
      </HashRouter>
    </div>
  )
}

export default App
